// ---------- Moteur d'i18n ----------

/**
 * Devine la langue du visiteur à partir de son navigateur (Intl/navigator.language),
 * uniquement s'il n'a jamais choisi de langue manuellement sur QuickAtlas (aucune
 * préférence enregistrée). Un choix manuel n'est jamais écrasé.
 */
function detectVisitorLanguage() {
  try {
    const saved = localStorage.getItem('atlas_lang');
    if (saved) return saved;
    const nav = (navigator.language || (navigator.languages && navigator.languages[0]) || 'en').toLowerCase();
    const base = nav.split('-')[0];
    const match = LANGUAGE_CATALOG.find((l) => l.code === base);
    return match ? match.code : 'en';
  } catch {
    return 'fr';
  }
}

const i18n = {
  current: detectVisitorLanguage(),

  effectiveLang() {
    const entry = LANGUAGE_CATALOG.find((l) => l.code === this.current);
    if (entry && entry.supported) return entry.code;
    if (entry && entry.fallback) return entry.fallback;
    return 'fr';
  },

  t(key, vars) {
    const lang = this.effectiveLang();
    let str = (T[lang] && T[lang][key]) || T.fr[key] || key;
    if (vars) {
      for (const [k, v] of Object.entries(vars)) str = str.replace(`{${k}}`, v);
    }
    return str;
  },

  setLanguage(code) {
    this.current = code;
    localStorage.setItem('atlas_lang', code);
    this.apply();
  },

  apply() {
    const lang = this.effectiveLang();
    const entry = LANGUAGE_CATALOG.find((l) => l.code === this.current);
    document.documentElement.lang = lang;
    document.documentElement.dir = (entry && entry.rtl) || (LANGUAGE_CATALOG.find((l) => l.code === lang) || {}).rtl ? 'rtl' : 'ltr';

    document.querySelectorAll('[data-i18n]').forEach((elm) => {
      elm.textContent = this.t(elm.getAttribute('data-i18n'));
    });
    document.querySelectorAll('[data-i18n-placeholder]').forEach((elm) => {
      elm.setAttribute('placeholder', this.t(elm.getAttribute('data-i18n-placeholder')));
    });

    const note = document.getElementById('langFallbackNote');
    if (note) {
      if (entry && !entry.supported) {
        note.hidden = false;
        note.textContent = this.t('lang.fallback_note', { dialect: entry.label, lang: LANGUAGE_CATALOG.find((l) => l.code === lang).label });
      } else {
        note.hidden = true;
      }
    }

    if (typeof onLanguageApplied === 'function') onLanguageApplied();
  },

  populateSelector(selectEl) {
    selectEl.innerHTML = '';
    const groups = {};
    for (const entry of LANGUAGE_CATALOG) {
      if (!groups[entry.group]) groups[entry.group] = [];
      groups[entry.group].push(entry);
    }
    for (const [groupName, entries] of Object.entries(groups)) {
      const optgroup = document.createElement('optgroup');
      optgroup.label = groupName;
      for (const entry of entries) {
        const opt = document.createElement('option');
        opt.value = entry.code;
        opt.textContent = entry.supported ? entry.label : `${entry.label} (bêta)`;
        optgroup.append(opt);
      }
      selectEl.append(optgroup);
    }
    selectEl.value = this.current;
  },
};
